<template>
  <div class="pr-root">
    <!-- Loading Overlay -->
    <v-overlay :value="loading" z-index="999">
      <div class="pr-loader">
        <div class="pr-loader__dots">
          <span></span><span></span><span></span>
        </div>
        <div class="pr-loader__text">Loading plan...</div>
      </div>
    </v-overlay>

    <!-- Verifying Access -->
    <div
      v-if="!accessChecked"
      class="d-flex flex-column align-center justify-center"
      style="min-height: 60vh"
    >
      <v-progress-circular
        indeterminate
        color="primary"
        size="52"
      ></v-progress-circular>
      <div class="mt-4 grey--text text--darken-1">Verifying access…</div>
    </div>

    <!-- Access Denied -->
    <div v-else-if="!isSupervisor" class="pr-empty">
      <div class="pr-empty__icon-wrap">
        <v-icon size="52" color="#dc2626">mdi-lock-outline</v-icon>
      </div>
      <h2 class="pr-empty__title">Access Restricted</h2>
      <p class="pr-empty__desc">
        This performance plan can only be reviewed by the staff member's
        assigned supervisor. Your account is not the assigned supervisor for
        this staff member.
      </p>
    </div>

    <template v-else>
    <!-- Hero Header -->
    <header class="pr-hero">
      <div class="pr-hero__pattern"></div>
      <div class="pr-hero__inner">
        <div class="pr-hero__breadcrumb">
          <span class="pr-hero__back" @click="$router.go(-1)">
            <v-icon size="13" color="rgba(255,255,255,0.6)"
              >mdi-arrow-left</v-icon
            >
            Back
          </span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <v-icon size="14" color="#f97316">mdi-home</v-icon>
          <span>Ministry of Health</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span>Performance Management</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span class="pr-hero__breadcrumb-active">Plan Review</span>
          <v-spacer></v-spacer>
          <span class="pr-hero__supervisor-tag">
            <v-icon size="12" color="#fdba74">mdi-shield-check</v-icon>
            Supervisor Review
          </span>
        </div>

        <div class="pr-hero__content">
          <div class="pr-hero__left">
            <div class="pr-hero__badge">
              <v-icon size="14" color="#f97316"
                >mdi-clipboard-check-outline</v-icon
              >
              Performance Plan Review
            </div>
            <div class="pr-hero__title-row">
              <h1 class="pr-hero__title">
                {{ performancePlan ? performancePlan.name : "Loading Plan…" }}
              </h1>
            </div>
            <div class="pr-hero__meta">
              <div v-if="staffName" class="pr-hero__meta-item">
                <v-icon size="15" color="#fdba74">mdi-account</v-icon>
                <span>{{ staffName }}</span>
              </div>
              <div v-if="staffName" class="pr-hero__meta-sep"></div>
              <div class="pr-hero__meta-item">
                <v-icon size="15" color="#fdba74">mdi-calendar</v-icon>
                <span>FY {{ selectedFiscalYear }}</span>
              </div>
              <div v-if="performancePlan" class="pr-hero__meta-sep"></div>
              <div
                v-if="performancePlan"
                class="pr-hero__status"
                :class="`pr-hero__status--${planStatus}`"
              >
                {{ statusLabel }}
              </div>
              <div v-if="reviews.length > 0" class="pr-hero__meta-sep"></div>
              <div v-if="reviews.length > 0" class="pr-hero__meta-item">
                <v-icon size="14" color="#fdba74">mdi-history</v-icon>
                <span
                  >{{ reviews.length }} previous review{{
                    reviews.length !== 1 ? "s" : ""
                  }}</span
                >
              </div>
            </div>
          </div>

          <div class="pr-hero__right" v-if="performancePlan">
            <div class="pr-hero__stats">
              <div class="pr-hero__stat">
                <div class="pr-hero__stat-num">{{ objectives.length }}</div>
                <div class="pr-hero__stat-label">Objectives</div>
              </div>
              <div class="pr-hero__stat-div"></div>
              <div class="pr-hero__stat">
                <div class="pr-hero__stat-num">{{ activities.length }}</div>
                <div class="pr-hero__stat-label">Activities</div>
              </div>
              <div class="pr-hero__stat-div"></div>
              <div class="pr-hero__stat">
                <div class="pr-hero__stat-num">{{ kpis.length }}</div>
                <div class="pr-hero__stat-label">KPIs</div>
              </div>
              <div class="pr-hero__stat-div"></div>
              <div class="pr-hero__stat">
                <div class="pr-hero__stat-num">{{ targets.length }}</div>
                <div class="pr-hero__stat-label">Targets</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>

    <!-- Body -->
    <div class="pr-body">
      <!-- No Plan State -->
      <div v-if="!loading && !performancePlan" class="pr-empty">
        <div class="pr-empty__icon-wrap">
          <v-icon size="52" color="#0d9488">mdi-file-search-outline</v-icon>
        </div>
        <h2 class="pr-empty__title">No submitted plan found</h2>
        <p class="pr-empty__desc">
          No plan has been submitted for review by this staff member for
          <strong>FY {{ selectedFiscalYear }}</strong
          >.
        </p>
      </div>

      <template v-else-if="performancePlan">
        <!-- ── Review History ──────────────────────────────── -->
        <v-row>
          <v-col
            :cols="
              () => {
                if (!reviews.length) {
                  return 0;
                } else if (reviews.length && planStatus === 'approved') {
                  return 12;
                } else {
                  return 6;
                }
              }
            "
          >
            <div v-if="reviews.length > 0" class="pr-section">
              <div class="pr-section__head">
                <v-icon size="16" color="#0d9488">mdi-history</v-icon>
                <span class="pr-section__title">Review History</span>
                <span class="pr-section__count"
                  >{{ reviews.length }} review{{
                    reviews.length !== 1 ? "s" : ""
                  }}</span
                >
              </div>
              <div class="pr-reviews-list">
                <div
                  v-for="(review, rIdx) in reviews"
                  :key="review.id"
                  class="pr-review-card"
                  :class="`pr-review-card--${review.decision}`"
                >
                  <div
                    class="pr-review-card__header"
                    @click="toggleReview(rIdx)"
                  >
                    <div class="pr-review-card__header-left">
                      <div
                        class="pr-review-decision-icon"
                        :class="`pr-review-decision-icon--${review.decision}`"
                      >
                        <v-icon
                          size="14"
                          :color="
                            review.decision === 'approved'
                              ? '#059669'
                              : '#dc2626'
                          "
                        >
                          {{
                            review.decision === "approved"
                              ? "mdi-check-circle"
                              : "mdi-close-circle"
                          }}
                        </v-icon>
                      </div>
                      <div>
                        <div class="pr-review-card__round">
                          Round {{ reviews.length - rIdx }}
                          <span
                            class="pr-review-card__decision-label"
                            :class="
                              `pr-review-card__decision-label--${review.decision}`
                            "
                          >
                            {{
                              review.decision === "approved"
                                ? "Approved"
                                : "Rejected"
                            }}
                          </span>
                        </div>
                        <div class="pr-review-card__meta">
                          <v-icon size="11" color="#94a3b8"
                            >mdi-clock-outline</v-icon
                          >
                          {{ formatDate(review.date) }}
                        </div>
                      </div>
                    </div>
                    <v-icon
                      size="16"
                      color="#94a3b8"
                      :class="{ 'pr-rotate': expandedReviews[rIdx] }"
                    >
                      mdi-chevron-down
                    </v-icon>
                  </div>
                  <v-expand-transition>
                    <div
                      v-if="expandedReviews[rIdx]"
                      class="pr-review-card__body"
                    >
                      <div
                        v-if="review.comment"
                        class="pr-review-card__comment"
                      >
                        <div class="pr-review-card__comment-label">
                          <v-icon size="12" color="#64748b"
                            >mdi-comment-text-outline</v-icon
                          >
                          Supervisor Comment
                        </div>
                        <p class="pr-review-card__comment-text">
                          {{ review.comment }}
                        </p>
                      </div>
                      <div v-else class="pr-review-card__no-comment">
                        No comment provided.
                      </div>
                    </div>
                  </v-expand-transition>
                </div>
              </div>
            </div>
          </v-col>

          <!-- ── Current Review Panel (supervisor action) ───── -->
          <v-col
            v-if="canReview"
            :cols="
              () => {
                if (!reviews.length && canReview) {
                  return 12;
                } else if (reviews.length && canReview) {
                  return 6;
                } else {
                  return 0;
                }
              }
            "
          >
            <div v-if="canReview" class="pr-review-action-panel">
              <div class="pr-review-action-panel__accent"></div>
              <div class="pr-review-action-panel__inner">
                <div class="pr-review-action-panel__head">
                  <div class="pr-review-action-panel__icon">
                    <v-icon size="20" color="white">mdi-clipboard-check</v-icon>
                  </div>
                  <div>
                    <div class="pr-review-action-panel__title">Your Review</div>
                    <div class="pr-review-action-panel__sub">
                      Review the plan below, then submit your decision.
                    </div>
                  </div>
                </div>
                <div class="pr-review-action-panel__form">
                  <v-form ref="reviewForm" v-model="validReview">
                    <div class="pr-field">
                      <label class="pr-field__lbl">
                        Comments
                        <span class="red--text">*</span>
                      </label>
                      <v-textarea
                        v-model="reviewComment"
                        :rules="[rules.required]"
                        outlined
                        dense
                        hide-details="auto"
                        rows="4"
                        class="pr-input"
                        placeholder="Provide feedback to the staff member — what was done well, what needs to change, or why you are approving/rejecting..."
                      />
                    </div>
                    <div class="pr-review-action-panel__actions">
                      <button
                        type="button"
                        class="pr-decision-btn pr-decision-btn--reject"
                        :disabled="!validReview || submitting"
                        @click="submitReview('rejected')"
                      >
                        <v-icon size="16">mdi-close-circle-outline</v-icon>
                        Reject & Return to Staff
                      </button>
                      <button
                        type="button"
                        class="pr-decision-btn pr-decision-btn--approve"
                        :disabled="!validReview || submitting"
                        @click="submitReview('approved')"
                      >
                        <v-icon size="16">mdi-check-circle-outline</v-icon>
                        Approve Plan
                      </button>
                    </div>
                  </v-form>
                </div>
              </div>
            </div>
          </v-col>
        </v-row>

        <!-- Already reviewed readonly banner -->
        <div
          v-if="alreadyReviewed && !canReview"
          class="pr-reviewed-banner"
          :class="`pr-reviewed-banner--${planStatus}`"
        >
          <v-icon
            size="18"
            :color="planStatus === 'approved' ? '#059669' : '#dc2626'"
          >
            {{
              planStatus === "approved"
                ? "mdi-check-circle"
                : "mdi-close-circle"
            }}
          </v-icon>
          <div>
            <div class="pr-reviewed-banner__title">
              You {{ planStatus === "approved" ? "approved" : "rejected" }} this
              plan
            </div>
            <div class="pr-reviewed-banner__sub">
              {{ latestReview ? formatDate(latestReview.date) : "" }} ·
              {{
                planStatus === "rejected"
                  ? "The plan has been returned to the staff member for revision."
                  : "This plan is now approved."
              }}
            </div>
          </div>
        </div>

        <!-- ── Plan Content ──────────────────────────────── -->
        <div class="pr-section">
          <div class="pr-section__head">
            <v-icon size="16" color="#0d9488">mdi-sitemap</v-icon>
            <span class="pr-section__title">Performance Plan</span>
            <span class="pr-section__count"
              >{{ objectives.length }} objective{{
                objectives.length !== 1 ? "s" : ""
              }}</span
            >
          </div>

          <performance-plan-objectives
            ref="objectivesPanel"
            :plan-id="performancePlan ? performancePlan.id : null"
            :can-edit="false"
            accent-color="teal"
            @data-loaded="onDataLoaded"
          />
        </div>
      </template>
    </div>
    </template>

    <!-- Confirm Review Dialog -->
    <v-dialog
      v-model="showConfirmDialog"
      max-width="460"
      content-class="pr-dialog"
    >
      <div
        class="pr-dialog__strip"
        :class="
          pendingDecision === 'approved'
            ? 'pr-dialog__strip--approve'
            : 'pr-dialog__strip--reject'
        "
      ></div>
      <div class="pr-dialog__inner">
        <div class="pr-dialog__head">
          <div
            class="pr-dialog__head-icon"
            :class="
              pendingDecision === 'approved'
                ? 'pr-dialog__head-icon--approve'
                : 'pr-dialog__head-icon--reject'
            "
          >
            <v-icon color="white" size="20">
              {{
                pendingDecision === "approved"
                  ? "mdi-check-circle"
                  : "mdi-close-circle"
              }}
            </v-icon>
          </div>
          <div>
            <div class="pr-dialog__title">
              {{
                pendingDecision === "approved" ? "Approve Plan" : "Reject Plan"
              }}
            </div>
            <div class="pr-dialog__sub">This action cannot be undone</div>
          </div>
          <button class="pr-dialog__x" @click="showConfirmDialog = false">
            <v-icon size="18" color="#94a3b8">mdi-close</v-icon>
          </button>
        </div>
        <div class="pr-dialog__body">
          <p class="pr-dialog__confirm-text">
            <template v-if="pendingDecision === 'approved'">
              You are about to <strong>approve</strong> this performance plan.
              The plan status will be updated to <em>Approved</em>.
            </template>
            <template v-else>
              You are about to <strong>reject</strong> this performance plan. It
              will be returned to <strong>{{ staffName }}</strong> for revision
              and resubmission.
            </template>
          </p>
          <div v-if="reviewComment" class="pr-dialog__comment-preview">
            <div class="pr-dialog__comment-preview-label">
              <v-icon size="12" color="#64748b"
                >mdi-comment-text-outline</v-icon
              >
              Your comment
            </div>
            <p>{{ reviewComment }}</p>
          </div>
          <div v-else class="pr-dialog__no-comment">
            <v-icon size="13" color="#94a3b8">mdi-information-outline</v-icon>
            No comment will be attached to this review.
          </div>
        </div>
        <div class="pr-dialog__foot">
          <button
            class="pr-btn pr-btn--ghost"
            @click="showConfirmDialog = false"
          >
            Go back
          </button>
          <button
            class="pr-btn"
            :class="
              pendingDecision === 'approved'
                ? 'pr-btn--approve'
                : 'pr-btn--reject'
            "
            :disabled="submitting"
            @click="confirmReview"
          >
            <v-progress-circular
              v-if="submitting"
              size="14"
              width="2"
              indeterminate
              color="white"
            />
            <v-icon v-else size="15">
              {{ pendingDecision === "approved" ? "mdi-check" : "mdi-send" }}
            </v-icon>
            {{
              pendingDecision === "approved"
                ? "Confirm Approval"
                : "Reject & Return"
            }}
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- Snackbar -->
    <v-snackbar
      v-model="snackbar"
      :color="snackbarColor"
      :timeout="3500"
      bottom
      right
    >
      <div class="d-flex align-center" style="gap: 8px">
        <v-icon left>{{ snackbarIcon }}</v-icon>
        {{ snackbarMessage }}
      </div>
      <template v-slot:action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar = false">✕</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";
import PerformancePlanObjectives from "./performance-plan-objectives.vue";

export default {
  name: "PerformancePlanReview",
  mixins: [generalMixin, processQuestionnaire],

  components: { PerformancePlanObjectives },

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/performance-plan",
      fhir: {},
      profile:
        "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",

      loading: false,
      submitting: false,
      selectedFiscalYear: "",
      accessChecked: false,
      isSupervisor: false,

      // Staff whose plan is being reviewed
      staffName: "",

      // Plan data
      performancePlan: null,
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],

      // Supervisor's targets linked to this staff's objectives
      supervisorTargetsByObjective: {},

      // Review history
      reviews: [],
      expandedReviews: {},
      // Current review form
      reviewComment: "",
      validReview: true,
      showConfirmDialog: false,
      pendingDecision: null, // 'approved' | 'rejected'

      // Snackbar
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      snackbarIcon: "mdi-check-circle",

      rules: {
        required: (value) => {
          if (value === undefined || value === null || value === "") {
            return "This field is required";
          }
          if (typeof value === "object" && !value.id) {
            return "This field is required";
          }
          return true;
        },
      },
    };
  },

  computed: {
    queries() {
      return this.$route?.query || {};
    },

    planStatus() {
      if (!this.performancePlan) return "no-plan";
      return this.performancePlan.status || "draft";
    },

    statusLabel() {
      const map = {
        draft: "Draft",
        submitted: "Submitted",
        approved: "Approved",
        rejected: "Rejected",
        active: "Active",
        undersupervisorreview: "Under Review",
        "no-plan": "No Plan",
      };
      return map[this.planStatus] || this.planStatus;
    },

    // Supervisor can review when plan is submitted and they haven't already reviewed this round
    canReview() {
      return this.planStatus === "undersupervisorreview";
    },

    alreadyReviewed() {
      return (
        this.reviews.length > 0 &&
        (this.planStatus === "approved" || this.planStatus === "rejected")
      );
    },

    latestReview() {
      return this.reviews.length > 0 ? this.reviews[0] : null;
    },
  },

  async mounted() {
    let fiscalYear = await fetch("/site/leave/getFinancialYear");
    fiscalYear = await fiscalYear.json();
    this.selectedFiscalYear = fiscalYear.year;

    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();

    if (!this.isSupervisor) {
      return;
    }

    await this.initialize();
  },

  methods: {
    // ── Bootstrap ────────────────────────────────────────────────────────────

    async checkAccess() {
      try {
        const supervisorId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!supervisorId) {
          this.isSupervisor = false;
          return;
        }

        const resp = await fetch(
          "/site/general/getSupervisor/" + this.queries.practitioner,
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const supervisor = await resp.json();

        this.isSupervisor = supervisor?.practitioner == supervisorId;
      } catch (err) {
        console.error("checkAccess error:", err);
        this.showSnackbar("Failed to verify supervisor access.", "error");
        this.isSupervisor = false;
      } finally {
        this.accessChecked = true;
      }
    },

    async initialize() {
      this.loading = true;
      try {
        await this.loadStaffName();
        await this.loadPlan();
        await this.loadReviews();
        // Open first objective by default
        // Open most recent review by default
        if (this.reviews.length > 0) {
          this.$set(this.expandedReviews, 0, true);
        }
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error loading plan data", "error");
      } finally {
        this.loading = false;
      }
    },

    async loadStaffName() {
      try {
        const practitioner = this.queries.practitioner;
        if (!practitioner) return;
        const r = await fetch(`/fhir/Practitioner/${practitioner}`);
        const p = await r.json();
        const name = p.name?.[0];
        if (name) {
          const parts = [
            ...(name.prefix || []),
            name.given?.join(" ") || "",
            name.family || "",
          ].filter(Boolean);
          this.staffName = parts.join(" ");
        }
      } catch (e) {
        console.error("Error loading staff name:", e);
      }
    },

    async loadPlan() {
      await this.loadPerformancePlan();
    },

    onDataLoaded({
      objectives,
      activities,
      subActivities,
      kpis,
      targets,
      supervisorTargetsByObjective,
    }) {
      this.objectives = objectives;
      this.activities = activities;
      this.subActivities = subActivities;
      this.kpis = kpis;
      this.targets = targets;
      this.supervisorTargetsByObjective = supervisorTargetsByObjective;
    },

    // ── FHIR Data Loading ────────────────────────────────────────────────────

    async loadPerformancePlan() {
      const practitioner = this.queries.practitioner;
      if (!practitioner) return;
      try {
        const r = await fetch(`/fhir/Basic/${this.queries.plan}`);
        const b = await r.json();
        if (b) {
          this.performancePlan = this.extractPlanData(b);
        } else {
          this.performancePlan = null;
        }
      } catch (e) {
        console.error(e);
      }
    },

    async loadReviews() {
      if (!this.performancePlan) return;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/supervisor-performance-plan-review-profile",
          performanceplan: `Basic/${this.performancePlan.id}`,
          _sort: "-_lastUpdated",
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.reviews = b.entry
          ? b.entry.map((e) => this.extractReviewData(e.resource))
          : [];
      } catch (e) {
        console.error(e);
      }
    },

    ext(resource, url) {
      return resource.extension?.find((e) => e.url.includes(url));
    },

    extractPlanData(r) {
      return {
        id: r.id,
        name: this.ext(r, "ihris-basic-name")?.valueString || "",
        description: this.ext(r, "description")?.valueString || "",
        fiscalYear: this.ext(r, "fiscal-year")?.valueString || "",
        status: this.ext(r, "request-status")?.valueCoding?.code || "draft",
      };
    },

    extractReviewData(r) {
      return {
        id: r.id,
        comment: this.ext(r, "description")?.valueString || "",
        decision: this.ext(r, "review-status")?.valueCoding?.code || "",
        reviewerRef:
          this.ext(r, "user-reference")?.valueReference?.reference || "",
        planRef:
          this.ext(r, "performance-plan-reference")?.valueReference
            ?.reference || "",
        date: r.meta?.lastUpdated,
      };
    },

    // ── UI helpers ───────────────────────────────────────────────────────────

    toggleReview(index) {
      this.$set(this.expandedReviews, index, !this.expandedReviews[index]);
    },

    formatDate(dateStr) {
      if (!dateStr) return "";
      try {
        return new Intl.DateTimeFormat("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }).format(new Date(dateStr));
      } catch {
        return dateStr;
      }
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      const icons = {
        success: "mdi-check-circle",
        error: "mdi-alert-circle",
        warning: "mdi-alert",
        info: "mdi-information",
      };
      this.snackbarIcon = icons[color] || "mdi-information";
      this.snackbar = true;
    },

    submitReview(decision) {
      this.pendingDecision = decision;
      this.showConfirmDialog = true;
    },

    async confirmReview() {
      this.submitting = true;
      try {
        this.afterSaveMessage =
          this.pendingDecision === "approved"
            ? "Plan approved successfully."
            : "Plan rejected and returned to staff.";
        this.fhir = {
          type: "review",
          decision: this.pendingDecision,
          planid: this.performancePlan.id,
          comment: this.reviewComment,
        };
        await this.processFHIR();
        this.performancePlan.status =
          this.pendingDecision === "approved" ? "approved" : "rejected";

        await this.loadReviews();
        this.$set(this.expandedReviews, 0, true);

        this.showConfirmDialog = false;
        this.reviewComment = "";
        this.pendingDecision = null;
      } catch (e) {
        console.error("Review submission error:", e);
        this.showSnackbar(
          "Error submitting review. Please try again.",
          "error",
        );
      } finally {
        this.submitting = false;
      }
    },
  },
};
</script>

